def _type_spec(value: ir.TypeRef) -> object:
    if value.kind in ("primitive", "named"):
        assert value.name is not None
        return value.name
    if value.kind == "vec":
        assert value.item is not None
        return {"vec": _type_spec(value.item)}
    if value.kind == "option":
        assert value.item is not None
        return {"option": _type_spec(value.item)}
    if value.kind == "result":
        assert value.ok is not None and value.err is not None
        return {"result": {"ok": _type_spec(value.ok), "err": _type_spec(value.err)}}
    raise ValueError(f"unsupported IR type kind {value.kind!r}")


def _field_spec(value: ir.Field) -> dict[str, object]:
    result: dict[str, object] = {"name": value.name, "type": _type_spec(value.type)}
    if value.doc:
        result["doc"] = value.doc
    return result


def _spec_dict(spec: ir.SpecIR) -> dict:
    return {
        "schema": spec.schema,
        "generator": spec.generator,
        "contract": {
            "name": spec.contract.name,
            "crate": spec.contract.crate,
            "version": spec.contract.version,
            "description": spec.contract.description,
        },
        "constants": {
            item.name: {"value": item.value, "type": item.type}
            for item in spec.constants
        },
        "functions": [
            {
                "name": item.name,
                "args": [_field_spec(argument) for argument in item.args],
                "returns": _type_spec(item.returns),
                "mutating": item.mutating,
                **({"error": item.error} if item.error is not None else {}),
                **({"doc": item.doc} if item.doc else {}),
            }
            for item in spec.functions
        ],
        "structs": [
            {
                "name": item.name,
                "fields": [_field_spec(field) for field in item.fields],
                **({"doc": item.doc} if item.doc else {}),
            }
            for item in spec.structs
        ],
        "enums": [
            {
                "name": item.name,
                "encoding": item.encoding,
                "cases": [
                    {
                        "name": case.name,
                        **({"value": case.value} if case.value is not None else {}),
                        **({"doc": case.doc} if case.doc else {}),
                    }
                    for case in item.cases
                ],
                **({"doc": item.doc} if item.doc else {}),
            }
            for item in spec.enums
        ],
        "unions": [
            {
                "name": item.name,
                "cases": [
                    {
                        "name": case.name,
                        "types": [_type_spec(value) for value in case.types],
                        **({"doc": case.doc} if case.doc else {}),
                    }
                    for case in item.cases
                ],
                **({"doc": item.doc} if item.doc else {}),
            }
            for item in spec.unions
        ],
        "events": [
            {
                "name": item.name,
                "topic": item.topic,
                "topicFields": [_field_spec(field) for field in item.topic_fields],
                "dataFields": [_field_spec(field) for field in item.data_fields],
                **({"doc": item.doc} if item.doc else {}),
            }
            for item in spec.events
        ],
    }


def read_functions(spec: dict) -> list[dict]:
    return [function for function in spec["functions"] if not function["mutating"]]


def type_names(spec: dict) -> tuple[set[str], set[str], set[str]]:
    return (
        {struct["name"] for struct in spec["structs"]},
        {enum["name"] for enum in spec["enums"]},
        {union["name"] for union in spec["unions"]},
    )


def event_types(spec: dict) -> set[str]:
    result: set[str] = set()
    for event in spec["events"]:
        for topic in event["topicFields"]:
            result.update(types_in(topic["type"]))
        for field in event["dataFields"]:
            result.update(types_in(field["type"]))
    return result


def types_in(value: object) -> set[str]:
    if isinstance(value, str):
        return {value} if value not in PRIMITIVES else set()
    if isinstance(value, list):
        return types_in(value[1])
    if isinstance(value, dict):
        if "option" in value:
            return types_in(value["option"])
        if "vec" in value:
            return types_in(value["vec"])
        if "map" in value:
            return types_in(value["key"]) | types_in(value["value"])
    return set()


def reachable_types(spec: dict) -> tuple[list[dict], list[dict], list[dict]]:
    structs, enums, unions = type_names(spec)
    required = event_types(spec)
    for function in read_functions(spec):
        for argument in function["args"]:
            required.update(types_in(argument["type"]))
        required.update(types_in(function["returns"]))

    changed = True
    while changed:
        changed = False
        for struct in spec["structs"]:
            if struct["name"] not in required:
                continue
            for field in struct["fields"]:
                for name in types_in(field["type"]):
                    if name not in required:
                        required.add(name)
                        changed = True
        for enum in spec["enums"]:
            if enum["name"] in required:
                for case in enum["cases"]:
                    for name in types_in(case.get("value")):
                        if name not in required:
                            required.add(name)
                            changed = True
        for union in spec["unions"]:
            if union["name"] in required:
                for case in union["cases"]:
                    for item_type in case["types"]:
                        for name in types_in(item_type):
                            if name not in required:
                                required.add(name)
                                changed = True

    return (
        [item for item in spec["structs"] if item["name"] in required & structs],
        [item for item in spec["enums"] if item["name"] in required & enums],
        [item for item in spec["unions"] if item["name"] in required & unions],
    )


def python_type(value: object) -> str:
    if isinstance(value, str):
        return PRIMITIVES[value][0] if value in PRIMITIVES else value
    if isinstance(value, list):
        inner = python_type(value[1])
        return f"list[{inner}]" if inner != "None" else "list[None]"
    if isinstance(value, dict):
        if "option" in value:
            inner = python_type(value["option"])
            return f"{inner} | None" if inner != "None" else "None"
        if "vec" in value:
            inner = python_type(value["vec"])
            return f"list[{inner}]" if inner != "None" else "list[None]"
        if "map" in value:
            return f"dict[{python_type(value['key'])}, {python_type(value['value'])}]"
    raise ValueError(f"unsupported spec type {value!r}")


def decode_expr(value: object, expression: str, context: str) -> str:
    if isinstance(value, str):
        if value not in PRIMITIVES:
            return f"{value}.from_scval({expression}, {context!r})"
        decoder = PRIMITIVES[value][1]
        if value == "u256":
            return f"{decoder}({expression}, 32, {context!r})"
        if value == "bytes32":
            return f"_decode_fixed_bytes({expression}, 32, {context!r})"
        if value == "bytes":
            return f"{decoder}({expression}, -1, {context!r})"
        return f"{decoder}({expression}, {context!r})"
    if isinstance(value, list):
        inner = decode_expr(value[1], "item", f"{context}[]")
        return f"_decode_vec({expression}, lambda item: {inner}, {context!r})"
    if isinstance(value, dict):
        if "option" in value:
            inner = decode_expr(value["option"], "item", context)
            return f"_decode_option({expression}, lambda item: {inner}, {context!r})"
        if "vec" in value:
            return decode_expr(["vec", value["vec"]], expression, context)
        if "map" in value:
            key = decode_expr(value["key"], "key", f"{context}.key")
            item = decode_expr(value["value"], "item", f"{context}.value")
            return (
                "{" + key + ": " + item + " for key, item in "
                f"_expect({expression}, 'map', {context!r})}}"
            )
    raise ValueError(f"unsupported spec type {value!r}")


def encode_expr(value: object, expression: str, context: str) -> str:
    if isinstance(value, str):
        if value not in PRIMITIVES:
            return f"_encode_{value}({expression}, {context!r})"
        encoder = PRIMITIVES[value][2]
        if value == "u256":
            return f"{encoder}({expression}, 32, {context!r})"
        if value == "bytes32":
            return f"_encode_fixed_bytes({expression}, 32, {context!r})"
        if value == "bytes":
            return f"{encoder}({expression}, -1, {context!r})"
        return f"{encoder}({expression}, {context!r})"
    if isinstance(value, list):
        inner = encode_expr(value[1], "item", f"{context}[]")
        return f"_encode_vec({expression}, lambda item: {inner}, {context!r})"
    if isinstance(value, dict):
        if "option" in value:
            inner = encode_expr(value["option"], "item", context)
            return f"_encode_option({expression}, lambda item: {inner}, {context!r})"
        if "vec" in value:
            return encode_expr(["vec", value["vec"]], expression, context)
        if "map" in value:
            key = encode_expr(value["key"], "key", f"{context}.key")
            item = encode_expr(value["value"], "item", f"{context}.value")
            return (
                "ScVal('map', tuple(sorted(((" + key + ", " + item +
                ") for key, item in " + expression + ".items()), "
                "key=lambda entry: _scval_sort_key(entry[0])))"
            )
    raise ValueError(f"unsupported spec type {value!r}")


def doc_lines(value: dict) -> list[str]:
    doc = value.get("doc", "")
    text = " ".join(line.strip() for line in doc.splitlines() if line.strip())
    text = text.replace('"""', '\\"\\"\\"')
    return [f'    """{text}"""'] if text else []


def generate_enum(enum: dict) -> list[str]:
    name = enum["name"]
    encoding = enum["encoding"]
    base = "IntEnum" if encoding == "u32" else "Enum"
    lines = [f"class {name}({base}):"]
    if enum.get("doc"):
        lines.extend(doc_lines(enum))
    for case in enum["cases"]:
        value = case["value"] if encoding == "u32" else case["name"]
        lines.append(f"    {case['name']} = {value!r}")
    if base == "Enum":
        lines.append("    def __str__(self) -> str:")
        lines.append("        return self.value")
    lines.append("")
    lines.append("    @classmethod")
    lines.append(f"    def from_scval(cls, value: ScVal, context: str = {name!r}) -> {name}:")
    if encoding == "symbol":
        lines.append(f"        tag = _enum_tag(value, context)")
    else:
        lines.append(f"        tag = _decode_u32(value, context)")
    lines.append("        try:")
    lines.append("            return cls(tag)")
    lines.append("        except ValueError as error:")
    lines.append(f"            raise DecodeError(f'{{context}}: unknown {name} case {{tag!r}}') from error")
    lines.append("")
    lines.append(f"def _encode_{name}(value: {name}, context: str) -> ScVal:")
    if encoding == "symbol":
        lines.append("    return ScVal('vec', (ScVal('symbol', value.value),))")
    else:
        lines.append("    return ScVal('u32', value.value)")
    lines.append("")
    return lines


def generate_struct(struct: dict) -> list[str]:
    name = struct["name"]
    lines = ["@dataclass(frozen=True)", f"class {name}(CanonicalMixin):"]
    if struct.get("doc"):
        lines.extend(doc_lines(struct))
    for field in struct["fields"]:
        lines.append(f"    {field['name']}: {python_type(field['type'])}")
    lines.extend(["", "    @classmethod", f"    def from_scval(cls, value: ScVal, context: str = {name!r}) -> {name}:"])
    lines.append(f"        fields = _struct_fields(value, context)")
    for field in struct["fields"]:
        field_name = field["name"]
        field_context = f"{name}.{field_name}"
        expression = f"_field(fields, {field_name!r}, {field_context!r})"
        decoded = decode_expr(field["type"], expression, field_context)
        if isinstance(field["type"], dict) and "option" in field["type"]:
            decoded = decode_expr(field["type"]["option"], "item", field_context)
            decoded = f"_optional_field(fields, {field_name!r}, lambda item: {decoded}, {field_context!r})"
        lines.append(f"        {field_name} = {decoded}")
    args = ", ".join(field["name"] for field in struct["fields"])
    lines.append(f"        return cls({args})")
    lines.extend(["", f"def _encode_{name}(value: {name}, context: str) -> ScVal:"])
    lines.append("    entries = []")
    for field in struct["fields"]:
        field_name = field["name"]
        encoded = encode_expr(field["type"], f"value.{field_name}", f"{name}.{field_name}")
        lines.append(f"    entries.append((ScVal('symbol', {field_name!r}), {encoded}))")
    lines.append("    return ScVal('map', tuple(sorted(entries, key=lambda entry: _scval_sort_key(entry[0]))))")
    lines.append("")
    return lines


def generate_union(union: dict) -> list[str]:
    name = union["name"]
    cases = union["cases"]
    lines = ["@dataclass(frozen=True)", f"class {name}(CanonicalMixin):"]
    lines.extend(["    variant: str", "    payload: tuple[Any, ...]"])
    lines.extend([
        "",
        "    @classmethod",
        f"    def from_scval(cls, value: ScVal, context: str = {name!r}) -> {name}:",
        "        items = _vec_items(value, context)",
        "        if not items:",
        f"            raise DecodeError(f'{{context}}: empty {name} vector')",
        "        variant = _decode_symbol(items[0], context + '.variant')",
    ])
    for case in cases:
        case_name = case["name"]
        types = case["types"]
        lines.append(f"        if variant == {case_name!r}:")
        lines.append(f"            if len(items) != {len(types) + 1}:")
        lines.append(f"                raise DecodeError(f'{{context}}: {case_name} payload arity mismatch')")
        if types:
            decoded = [decode_expr(item_type, f"items[{index}]", f"{name}.{case_name}[{index}]") for index, item_type in enumerate(types, 1)]
            lines.append(f"            return cls({case_name!r}, (" + ", ".join(decoded) + ",))")
        else:
            lines.append(f"            return cls({case_name!r}, ())")
    lines.append(f"        raise DecodeError(f'{{context}}: unknown {name} variant {{variant!r}}')")
    lines.extend(["", f"def _encode_{name}(value: {name}, context: str) -> ScVal:"])
    for case in cases:
        case_name = case["name"]
        types = case["types"]
        lines.append(f"    if value.variant == {case_name!r}:")
        lines.append(f"        if len(value.payload) != {len(types)}:")
        lines.append(f"            raise EncodeError(f'{{context}}: {case_name} payload arity mismatch')")
        encoded = [encode_expr(item_type, f"value.payload[{index}]", f"{name}.{case_name}[{index}]") for index, item_type in enumerate(types)]
        items = ", ".join([f"ScVal('symbol', {case_name!r})", *encoded])
        lines.append(f"        return ScVal('vec', ({items}))" if encoded else f"        return ScVal('vec', (ScVal('symbol', {case_name!r}),))")
    lines.append(f"    raise EncodeError(f'{{context}}: unknown {name} variant')")
    lines.append("")
    return lines


def generate_error_enum(errors: list[tuple[int, str]]) -> list[str]:
    lines = ["class StreamError(IntEnum):", "    \"\"\"Canonical contract error codes shared by every StreamPay SDK.\"\"\""]
    for code, name in errors:
        lines.append(f"    {name} = {code}")
    lines.extend(["", "    @classmethod", "    def from_code(cls, code: int) -> StreamError | int:"])
    lines.append("        try:")
    lines.append("            return cls(code)")
    lines.append("        except ValueError:")
    lines.append("            return code")
    lines.extend([
        "",
        "",
        "def decode_contract_error(encoded: bytes | str) -> StreamError | int | None:",
        "    value = decode_scval(encoded)",
        "    if value.kind != 'error':",
        "        return None",
        "    return StreamError.from_code(value.value)",
        "",
        "",
        "def _reject_contract_error(value: ScVal) -> None:",
        "    if value.kind != 'error':",
        "        return",
        "    error = StreamError.from_code(value.value)",
        "    name = error.name if isinstance(error, StreamError) else 'UnknownContractError'",
        "    raise ContractError(value.value, name, error) from None",
        "",
    ])
    return lines


def generate_event(event: dict) -> list[str]:
    name = event["name"]
    topics = event["topicFields"]
    data_fields = event["dataFields"]
    lines = ["@dataclass(frozen=True)", f"class {name}(EventBase):"]
    if event.get("doc"):
        lines.extend(doc_lines(event))
    lines.append(f"    name: ClassVar[str] = {name!r}")
    lines.append("    contract_id: str")
    topic_names = ", ".join(repr(topic["name"]) for topic in topics)
    if len(topics) == 1:
        topic_names += ","
    lines.append(f"    topic_fields: ClassVar[tuple[str, ...]] = ({topic_names})")
    data_names = ", ".join(repr(field["name"]) for field in data_fields)
    if len(data_fields) == 1:
        data_names += ","
    lines.append(f"    data_fields: ClassVar[tuple[str, ...]] = ({data_names})")
    for topic in topics:
        lines.append(f"    {topic['name']}: {python_type(topic['type'])}")
    for field in data_fields:
        lines.append(f"    {field['name']}: {python_type(field['type'])}")
    lines.extend(["", "    @classmethod", f"    def from_parts(cls, event: ContractEvent, context: str = {name!r}) -> {name}:"])
    lines.append("        if event.event_type != 1 or event.topics is None or event.data is None:")
    lines.append(f"            raise DecodeError(f'{{context}}: expected a contract event body')")
    lines.append("        topics = event.topics")
    lines.append(f"        if len(topics) != {len(topics) + 1}:")
    lines.append(f"            raise DecodeError(f'{{context}}: expected {len(topics) + 1} event topics, got {{len(topics)}}')")
    for index, topic in enumerate(topics, 1):
        context = f"{name}.{topic['name']}"
        decoded = decode_expr(topic["type"], f"_topic(topics, {index}, context)", context)
        lines.append(f"        {topic['name']} = {decoded}")
    lines.append(f"        data = _struct_fields(event.data, {name!r})")
    for field in data_fields:
        context = f"{name}.{field['name']}"
        if isinstance(field["type"], dict) and "option" in field["type"]:
            decoded = decode_expr(field["type"]["option"], "item", context)
            decoded = f"_optional_field(data, {field['name']!r}, lambda item: {decoded}, {context!r})"
        else:
            decoded = decode_expr(field["type"], f"_field(data, {field['name']!r}, context)", context)
        lines.append(f"        {field['name']} = {decoded}")
    names = ["contract_id=event.contract_id"]
    names.extend(f"{topic['name']}={topic['name']}" for topic in topics)
    names.extend(f"{field['name']}={field['name']}" for field in data_fields)
    lines.append("        return cls(" + ", ".join(names) + ")")
    lines.append("")
    return lines


def generate_function(function: dict) -> list[str]:
    name = function["name"]
    args_name = f"{name}_args"
    decoder_name = f"decode_{name}_result"
    signature = ", ".join(f"{arg['name']}: {python_type(arg['type'])}" for arg in function["args"])
    lines = [f"def {args_name}({signature}) -> list[bytes]:"]
    lines.append(f"    \"\"\"Encode ScVal arguments for {name}; this does not submit a transaction.\"\"\"")
    lines.append("    return [")
    for arg in function["args"]:
        context = f"{name}.{arg['name']}"
        encoded = encode_expr(arg["type"], arg["name"], context)
        lines.append(f"        {encoded}.to_xdr(),")
    lines.append("    ]")
    lines.extend(["", "", f"def {decoder_name}(encoded: bytes | str) -> {python_type(function['returns'])}:"])
    lines.append(f"    \"\"\"Decode the result of {name}; contract errors raise ContractError.\"\"\"")
    lines.append("    value = decode_scval(encoded)")
    lines.append("    _reject_contract_error(value)")
    decoded = decode_expr(function["returns"], "value", name)
    lines.append(f"    return {decoded}")
    lines.append("")
    return lines


def generate_client(functions: list[dict]) -> list[str]:
    lines = ["class ReadClient:"]
    lines.append('    """Transport-agnostic read-only client. No signing or submission methods are exposed."""')
    lines.extend(["", "    def __init__(self, transport: ReadTransport) -> None:", "        self._transport = transport", ""])
    lines.append("    def _call(self, method: str, args: Sequence[bytes], decoder: Any) -> Any:")
    lines.append("        return decoder(self._transport.simulate(method, args))")
    for function in functions:
        name = function["name"]
        signature = ", ".join(f"{arg['name']}: {python_type(arg['type'])}" for arg in function["args"])
        lines.extend(["", "    def " + name + f"(self, {signature}) -> {python_type(function['returns'])}:"])
        if function.get("doc"):
            doc = " ".join(line.strip() for line in function["doc"].splitlines() if line.strip())
            doc = doc.replace('"""', '\\"\\"\\"')
            lines.append(f'        """{doc}"""')
        call_args = ", ".join(arg["name"] for arg in function["args"])
        lines.append(f"        return self._call({name!r}, {name}_args({call_args}), decode_{name}_result)")
    lines.append("")
    return lines


def generate_event_decoder(events: list[dict]) -> list[str]:
    event_names = [event["name"] for event in events]
    lines = ["StreamPayEvent: TypeAlias = " + " | ".join(event_names)]
    lines.extend(["", "", "def decode_stream_pay_event(encoded: bytes | str, contract_id: str) -> StreamPayEvent | None:"])
    lines.append('    """Decode an event only when its contract ID and topic identify a StreamPay event."""')
    lines.append("    event = decode_contract_event(encoded)")
    lines.append("    if event.contract_id is None or event.contract_id.lower() != contract_id.lower():")
    lines.append("        return None")
    lines.append("    if event.event_type != 1 or event.topics is None or not event.topics:")
    lines.append("        return None")
    lines.append("    topic = event.topics[0]")
    lines.append("    if topic.kind != 'symbol':")
    lines.append("        return None")
    for event in events:
        name = event["name"]
        lines.append(f"    if topic.value == {event['topic']!r}:")
        lines.append(f"        return {name}.from_parts(event, {name!r})")
    lines.append("    return None")
    lines.append("")
    return lines


def outputs(spec: ir.SpecIR | dict, fingerprint: str, errors: list[tuple[int, str]]) -> dict[Path, str]:
    if isinstance(spec, ir.SpecIR):
        spec = _spec_dict(spec)
    structs, enums, unions = reachable_types(spec)
    functions = read_functions(spec)
    events = spec["events"]
    lines = [HEADER.format(fingerprint=fingerprint).rstrip(), "", RUNTIME_IMPORTS.rstrip(), ""]
    lines.append(f"SPEC_FINGERPRINT = {fingerprint!r}")
    lines.append(f"CONTRACT_VERSION = {spec['contract']['version']!r}")
    for name, constant in spec.get("constants", {}).items():
        lines.append(f"{name} = {constant['value']!r}")
    lines.append("")
    for function in functions:
        lines.append(f"{function['name'].upper()} = {function['name']!r}")
    lines.append("")
    lines.extend(generate_error_enum(errors))
    for enum in enums:
        lines.extend(generate_enum(enum))
    for union in unions:
        lines.extend(generate_union(union))
    for struct in structs:
        lines.extend(generate_struct(struct))
    for event in events:
        lines.extend(generate_event(event))
    for function in functions:
        lines.extend(generate_function(function))
    lines.extend(generate_client(functions))
    lines.extend(generate_event_decoder(events))

    public = ["SPEC_FINGERPRINT", "CONTRACT_VERSION", "StreamError", "ReadClient", "StreamPayEvent"]
    public.extend(spec.get("constants", {}))
    public.extend(function["name"].upper() for function in functions)
    public.extend(struct["name"] for struct in structs)
    public.extend(enum["name"] for enum in enums)
    public.extend(union["name"] for union in unions)
    public.extend(event["name"] for event in events)
    public.extend(f"{function['name']}_args" for function in functions)
    public.extend(f"decode_{function['name']}_result" for function in functions)
    public.extend(["decode_contract_error", "decode_stream_pay_event", "ScVal", "decode_scval"])
    lines.append("__all__ = [")
    for name in public:
        lines.append(f"    {name!r},")
    lines.append("]")
    lines.append("")
    return {PACKAGE_DIR / "src" / "streampay" / "_generated.py": "\n".join(lines)}
